local NewViewBaseLayer = require("hall.NewViewBaseLayer")
local phoneBind = class("phoneBind", NewViewBaseLayer)
local CommonTips = require("hall.tips.CommonTips")
local FamilyUntils = require("hall.familyCircle.FamilyUntils")
function phoneBind:ctor()
    phoneBind.super.ctor(self, "hall/res/hallMain/phoneBind.csb")
    self.isCanLogin = true
end

function phoneBind:onClickBtnComirt(sender, event)
    local phone = self.phoneFild:getString()
    if(self:checkPhone(phone)~=true)then
        CommonTips:showTips(FamilyUntils:SetCommTipLabel("请输入正确的手机号！"))
        return
    end
    local pwd = self.pwdFild:getString()
    if pwd == "" then
        return
    end
    local code = self.codeFild:getString()
    if code == "" then
        return
    end

    local tbl = {}
    tbl["password"] = pwd
    tbl["code"] = code
    tbl["phone"] = phone
    tbl["userId"] = USER_INFO["uid"]
    tbl["type"] =  "P"
    dump(tbl, "-----绑定-----")
    cct.createHttRq({

        url = HttpAddr .. "/bindPhoneBySms",
        date = tbl,
        type_ = "POST",

        callBack = function(data)
            local returnCode = tonumber(json.decode(data.netData).returnCode)
            dump(json.decode(data.netData),"json.decode(data.netData)")
            if 0 == tonumber(returnCode) then
                self:removeSelf()
                CommonTips:showTips(FamilyUntils:SetCommTipLabel("绑定成功！"))
            else
                CommonTips:showTips(FamilyUntils:SetCommTipLabel(json.decode(data.netData).error))

            end
        end})

end
